public class ContactTriggerHandler {
    private static Map<Id, Account> accountsById = new Map<Id, Account>();

    public void beforeInsert(List<Contact> newContacts) {
        loadAccounts(newContacts);

        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                Account a = accountsById.get(c.AccountId);
                if (a == null) {
                    continue;
                }
                if (String.isBlank(c.MailingCountry)) {
                    c.MailingCountry = a.BillingCountry;
                }
                if (String.isBlank(c.LeadSource)) {
                    c.LeadSource = a.AccountSource;
                }
            }
        }
    }

    public void beforeUpdate(List<Contact> newContacts) {
        loadAccounts(newContacts);

        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                Account a = accountsById.get(c.AccountId);
                if (a == null) {
                    continue;
                }
                if (String.isBlank(c.MailingCountry)) {
                    c.MailingCountry = a.BillingCountry;
                }
            }
        }
    }

    public void afterInsert(List<Contact> newContacts) {
        List<Account> accountsToUpdate = new List<Account>();

        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                Account a = accountsById.get(c.AccountId);
                if (a != null && String.isBlank(a.Phone)) {
                    a.Phone = c.Phone;
                    accountsToUpdate.add(a);
                }
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private void loadAccounts(List<Contact> contacts) {
        accountsById.clear();

        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (!accountIds.isEmpty()) {
            for (Account a : [
                SELECT Id, BillingCountry, AccountSource, Phone
                FROM Account
                WHERE Id IN :accountIds
            ]) {
                accountsById.put(a.Id, a);
            }
        }
    }
}
```

