public static void triggerHandler(Type domainType)
{
    fflib_SObjectDomain domain = (fflib_SObjectDomain) getDomain(domainType);

    if (Trigger.isBefore)
    {
        if (Trigger.isInsert)
        {
            domain.onApplyDefaults();
            domain.onBeforeInsert();
            domain.onValidate();
        }
        else if (Trigger.isUpdate)
        {
            domain.onApplyDefaults();
            domain.onBeforeUpdate();
            domain.onValidate();
        }
        else if (Trigger.isDelete)
        {
            domain.onBeforeDelete();
        }
    }
    else if (Trigger.isAfter)
    {
        if (Trigger.isInsert) domain.onAfterInsert();
        else if (Trigger.isUpdate) domain.onAfterUpdate();
        else if (Trigger.isDelete) domain.onAfterDelete();
        else if (Trigger.isUndelete) domain.onAfterUndelete();
    }
}
