trigger CaseTrigger on Case (after update) {
    // After update allows us to compare the old and new IsClosed values.
    // Enqueueing one Queueable job per case keeps each case isolated and makes
    // the survey work asynchronous for the future vendor integration.
    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);

        // Only enqueue for cases that transition from not closed to closed
        // and that still have a contact.
        if (oldCase != null
            && !oldCase.IsClosed
            && c.IsClosed
            && c.ContactId != null) {
            System.enqueueJob(new CaseSurveyJob(c.Id));
        }
    }
}
