import { LightningElement, api } from 'lwc';
import favoriteAddLabel from '@salesforce/label/c.Favorite_Add';
import favoriteRemoveLabel from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    @api favorite = false;

    get actionLabel() {
        return this.favorite ? favoriteRemoveLabel : favoriteAddLabel;
    }

    get ariaPressed() {
        return this.favorite ? 'true' : 'false';
    }

    handleClick() {
        const newFavorite = !this.favorite;
        this.favorite = newFavorite;
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: newFavorite }
            })
        );
    }
}

