    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null && parentId != null) {
                contactIds.add(childId);
                contactIds.add(parentId);
            }
        }

        if (contactIds.isEmpty()) {
            return;
        }

        // One query: get all Relationship Lookup records and any existing
        // relationships involving the child/parent contacts.
        Map<String, Id> typeIdByName = new Map<String, Id>();
        Set<String> existingRelationshipKeys = new Set<String>();

        for (npe4__Relationship_Lookup__c lookup : [
            SELECT Id, Name, npe4__Male__c, npe4__Female__c, npe4__Neutral__c, npe4__Active__c,
                   (SELECT Id, npe4__Contact__c, npe4__RelatedContact__c
                    FROM npe4__Relationships__r
                    WHERE npe4__Contact__c IN :contactIds
                       OR npe4__RelatedContact__c IN :contactIds)
            FROM npe4__Relationship_Lookup__c
        ]) {
            if (lookup.npe4__Active__c) {
                typeIdByName.put(lookup.Name, lookup.Id);
            }

            if (lookup.npe4__Relationships__r != null) {
                for (npe4__Relationship__c rel : lookup.npe4__Relationships__r) {
                    if (rel.npe4__Contact__c != null && rel.npe4__RelatedContact__c != null) {
                        existingRelationshipKeys.add(
                            rel.npe4__Contact__c + ':' + rel.npe4__RelatedContact__c
