public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_AMOUNT = 5000;
    private static final String CLOSED_WON_STAGE = 'Closed Won';

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
            && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        Map<Id, Opportunity> oldOppsById = new Map<Id, Opportunity>();
        if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate && oldlist != null) {
            for (SObject oldSObject : oldlist) {
                oldOppsById.put(oldSObject.Id, (Opportunity) oldSObject);
            }
        }

        List<SObject> tasksToInsert = new List<SObject>();

        for (SObject sObject : newlist) {
            Opportunity opp = (Opportunity) sObject;

            if (!isMajorGift(opp)) {
                continue;
            }

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                Opportunity oldOpp = oldOppsById.get(opp.Id);
                if (oldOpp != null && isMajorGift(oldOpp)) {
                    continue;
                }
            }

            Task task = new Task();
            task.Subject = 'Major gift thank-you call';
            task.Priority = 'High';
            task.Status = 'Not Started';
            task.WhatId = opp.Id;
            task.WhoId = opp.npsp__Primary_Contact__c;
            task.OwnerId = opp.OwnerId;
            if (opp.CloseDate != null) {
                task.ActivityDate = opp.CloseDate.addDays(3);
            }
            tasksToInsert.add(task);
        }

        dmlWrapper.objectsToInsert.addAll(tasksToInsert);
        return dmlWrapper;
    }

    private static Boolean isMajorGift(Opportunity opp) {
        return opp.StageName == CLOSED_WON_STAGE
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_AMOUNT;
    }
}
```

