File: force-app/main/default/classes/TA_Opportunity_LogAmountChange.cls
```apex
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static Set<Id> loggedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Opportunity> oldOpportunities = new Map<Id, Opportunity>();
        for (SObject oldRecord : triggerOld) {
            oldOpportunities.put(oldRecord.Id, (Opportunity) oldRecord);
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject newRecord : triggerNew) {
            Opportunity opportunity = (Opportunity) newRecord;
            Opportunity oldOpportunity = oldOpportunities.get(opportunity.Id);

            if (oldOpportunity == null) {
                continue;
            }

            if (opportunity.Amount == oldOpportunity.Amount) {
                continue;
            }

            Integer timesSeen = TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(opportunity.Id);
            if ((timesSeen == null || timesSeen == 1) && !loggedOpportunityIds.contains(opportunity.Id)) {
                tasksToInsert.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = opportunity.Id,
                    Status = 'Completed'
                ));
                loggedOpportunityIds.add(opportunity.Id);
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
```

